&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight vue"&gt;&lt;code&gt;



import { ref, onMounted, onUnmounted, watchEffect } from 'vue';
import { useIntersectionObserver } from '&lt;span class="nt"&gt;&amp;lt;a&lt;/span&gt; &lt;span class="na"&gt;href=&lt;/span&gt;&lt;span class="s"&gt;"https://github.com/vueuse/vueuse"&lt;/span&gt;&lt;span class="nt"&gt;&amp;gt;&lt;/span&gt;@vueuse/core&lt;span class="nt"&gt;&amp;lt;/a&amp;gt;&lt;/span&gt;'; // Vue 3.5 compatible utility

// Props definition with TypeScript
const props = defineProps&lt;span class="nt"&gt;&amp;lt;&lt;/span&gt;&lt;span class="err"&gt;{&lt;/span&gt;
&lt;span class="na"&gt;productId:&lt;/span&gt; &lt;span class="na"&gt;string&lt;/span&gt;&lt;span class="err"&gt;;&lt;/span&gt;
&lt;span class="err"&gt;}&lt;/span&gt;&lt;span class="nt"&gt;&amp;gt;&lt;/span&gt;();

// Reactive state
const product = ref&lt;span class="nt"&gt;&amp;lt;&lt;/span&gt;&lt;span class="err"&gt;{&lt;/span&gt;
&lt;span class="na"&gt;id:&lt;/span&gt; &lt;span class="na"&gt;string&lt;/span&gt;&lt;span class="err"&gt;;&lt;/span&gt;
&lt;span class="na"&gt;name:&lt;/span&gt; &lt;span class="na"&gt;string&lt;/span&gt;&lt;span class="err"&gt;;&lt;/span&gt;
&lt;span class="na"&gt;price:&lt;/span&gt; &lt;span class="na"&gt;number&lt;/span&gt;&lt;span class="err"&gt;;&lt;/span&gt;
&lt;span class="na"&gt;thumbnail:&lt;/span&gt; &lt;span class="na"&gt;string&lt;/span&gt;&lt;span class="err"&gt;;&lt;/span&gt;
&lt;span class="err"&gt;}&lt;/span&gt; &lt;span class="err"&gt;|&lt;/span&gt; &lt;span class="na"&gt;null&lt;/span&gt;&lt;span class="nt"&gt;&amp;gt;&lt;/span&gt;(null);
const isLoading = ref(true);
const hasError = ref(false);
const errorMessage = ref('');
const isHydrated = ref(false);
const productCardRef = ref(null);

// Intersection observer for partial hydration (Vapor mode compatible)
const { stop } = useIntersectionObserver(
productCardRef,
([{ isIntersecting }]) =&amp;gt; {
if (isIntersecting) {
isHydrated.value = true;
stop(); // Stop observing once hydrated
}
},
{ rootMargin: '200px' }
);

// Data fetching with error handling
const fetchProduct = async () =&amp;gt; {
try {
isLoading.value = true;
hasError.value = false;
const response = await fetch(`https://api.example.com/products/${props.productId}`);
if (!response.ok) {
throw new Error(`HTTP error! Status: ${response.status}`);
}
const data = await response.json();
product.value = data;
} catch (err) {
hasError.value = true;
errorMessage.value = err instanceof Error ? err.message : 'Failed to load product';
// Log to error tracking
if (window.Sentry) {
window.Sentry.captureException(err);
}
} finally {
isLoading.value = false;
}
};

// Watch for hydration state to trigger fetch
watchEffect(() =&amp;gt; {
if (isHydrated.value &lt;span class="err"&gt;&amp;amp;&amp;amp;&lt;/span&gt; !product.value &lt;span class="err"&gt;&amp;amp;&amp;amp;&lt;/span&gt; !hasError.value) {
fetchProduct();
}
});

// Cleanup observer on unmount
onUnmounted(() =&amp;gt; {
stop();
});






.product-card-container {
margin: 1rem;
min-height: 400px;
}

.product-card {
border: 1px solid #e5e7eb;
border-radius: 8px;
padding: 1rem;
